Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 100;
        const FINISH_LINE_Z = -TRACK_LENGTH;
        const CAR_WIDTH = 2;
        const CAR_HEIGHT = 1.2;
        const CAR_LENGTH = 4;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 400);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = -100;
        ground.receiveShadow = true;
        scene.add(ground);

        // Road
        const roadGeo = new THREE.PlaneGeometry(20, 400);
        const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const road = new THREE.Mesh(roadGeo, roadMat);
        road.rotation.x = -Math.PI / 2;
        road.position.y = 0.01;
        road.position.z = -100;
        road.receiveShadow = true;
        scene.add(road);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(20, 2);
        const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.z = FINISH_LINE_Z;
        finishLine.position.y = 0.02;
        scene.add(finishLine);

        // Checkered pattern on finish line (simple visual aid)
        const checkerGeo = new THREE.PlaneGeometry(20, 2);
        const checkerCanvas = document.createElement('canvas');
        checkerCanvas.width = 64;
        checkerCanvas.height = 64;
        const ctx = checkerCanvas.getContext('2d');
        ctx.fillStyle = 'white';
        ctx.fillRect(0,0,64,64);
        ctx.fillStyle = 'black';
        ctx.fillRect(0,0,32,32);
        ctx.fillRect(32,32,32,32);
        const checkerTex = new THREE.CanvasTexture(checkerCanvas);
        checkerTex.magFilter = THREE.NearestFilter;
        const checkerMat = new THREE.MeshBasicMaterial({ map: checkerTex });
        const checker = new THREE.Mesh(checkerGeo, checkerMat);
        checker.rotation.x = -Math.PI / 2;
        checker.position.z = FINISH_LINE_Z;
        checker.position.y = 0.03;
        scene.add(checker);

        // --- Car Builder ---
        function createCar(colorHex) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(CAR_WIDTH, CAR_HEIGHT * 0.6, CAR_LENGTH);
            const chassisMat = new THREE.MeshStandardMaterial({ color: colorHex });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = CAR_HEIGHT * 0.3;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(CAR_WIDTH * 0.8, CAR_HEIGHT * 0.4, CAR_LENGTH * 0.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = CAR_HEIGHT * 0.6 + CAR_HEIGHT * 0.2;
            cabin.position.z = -CAR_LENGTH * 0.1;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const wheelPositions = [
                { x: -1, z: 1.2 }, { x: 1, z: 1.2 },
                { x: -1, z: -1.2 }, { x: 1, z: -1.2 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        // --- Create Cars ---
        const redCar = createCar(0xff0000);
        redCar.position.set(3, 0, 0); // Right lane
        scene.add(redCar);

        const blueCar = createCar(0x0000ff);
        blueCar.position.set(-3, 0, 0); // Left lane
        scene.add(blueCar);

        // --- Animation Logic ---
        let startTime = 0;
        let isResetting = false;
        let resetTimer = 0;
        const RESET_DURATION = 2.0; // seconds

        // Car State
        const carState = {
            red: { t: 0, speed: 0 },
            blue: { t: 0, speed: 0 }
        };

        function resetRace() {
            isResetting = true;
            resetTimer = RESET_DURATION;
            carState.red.t = 0;
            carState.blue.t = 0;
        }

        function updateCars(dt) {
            if (isResetting) {
                resetTimer -= dt;
                if (resetTimer <= 0) {
                    isResetting = false;
                } else {
                    // Move cars back to start smoothly
                    const lerpSpeed = 5 * dt;
                    redCar.position.z = THREE.MathUtils.lerp(redCar.position.z, 0, lerpSpeed);
                    blueCar.position.z = THREE.MathUtils.lerp(blueCar.position.z, 0, lerpSpeed);
                    return;
                }
            }

            // --- Physics / Logic ---
            // Time t goes from 0 to 1 for the race duration.
            // We use a fixed race duration for consistency, e.g., 8 seconds.
            const raceDuration = 8.0; 
            const dtNormalized = dt / raceDuration;

            // Blue Car Logic: Starts fast, maintains steady speed
            // Position logic: z = - (speed * time)
            // We simulate acceleration curves.

            // Red Car Logic: Starts slow, accelerates heavily after t=0.4

            // Simple simulation variables
            let redSpeed = 0;
            let blueSpeed = 0;

            // Calculate progress based on time
            // We will update positions directly based on a velocity profile

            // Blue Car Velocity Profile: High constant speed
            blueSpeed = 12.0; // units per second

            // Red Car Velocity Profile: 
            // 0.0 - 0.4s: Slow (5.0)
            // 0.4 - 1.0s: Accelerates to 18.0

            let redBaseSpeed = 5.0;
            let redMaxSpeed = 18.0;

            // Current race time in seconds (approx)
            // We track cumulative distance to derive time or just track time directly
            // Let's track time directly for simplicity
            carState.red.t += dt;
            carState.blue.t += dt;

            // Calculate speeds based on time
            if (carState.red.t < 0.4) {
                redSpeed = 5.0;
            } else {
                // Interpolate from 5 to 18 between 0.4 and 1.0
                const progress = Math.min((carState.red.t - 0.4) / 0.6, 1.0);
                redSpeed = 5.0 + (13.0 * progress);
            }

            // Update Positions
            redCar.position.z -= redSpeed * dt;
            blueCar.position.z -= blueSpeed * dt;

            // Check Finish
            if (redCar.position.z <= FINISH_LINE_Z) {
                // Red wins
                resetRace();
            }

            // Ensure cars don't go infinitely back if logic fails
            if (redCar.position.z < FINISH_LINE_Z - 10) resetRace();
            if (blueCar.position.z < FINISH_LINE_Z - 10) resetRace();

            // Visual Tilt (lean into turns/acceleration)
            // Red leans forward when accelerating
            const accel = redSpeed > 10 ? 0.05 : -0.02;
            redCar.rotation.x = THREE.MathUtils.lerp(redCar.rotation.x, accel, 0.1);

            // Blue is steady
            blueCar.rotation.x = THREE.MathUtils.lerp(blueCar.rotation.x, 0, 0.1);
        }

        function updateCamera() {
            // Camera follows the midpoint between the two cars
            const midX = (redCar.position.x + blueCar.position.x) / 2;
            const midZ = (redCar.position.z + blueCar.position.z) / 2;

            // Keep camera behind the cars, looking forward
            const camZ = midZ + 15; // Behind
            const camY = 8; // Height
            const camX = 0; // Centered horizontally roughly

            camera.position.z = camZ;
            camera.position.y = camY;
            camera.position.x = camX;

            // Look at a point ahead of the cars
            camera.lookAt(midX, 1, midZ - 20);
        }

        // --- Main Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const dt = Math.min(clock.getDelta(), 0.1); // Cap dt to prevent physics explosions

            updateCars(dt);
            updateCamera();

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
